-- Player-measured 53-point ride, followed by three original drive-away points.
-- New path keeps previous 4492801 and custom paths untouched.
DROP TEMPORARY TABLE IF EXISTS `_exodus_measured`;
CREATE TEMPORARY TABLE `_exodus_measured` LIKE `waypoint_data`;
DROP TEMPORARY TABLE IF EXISTS `_exodus_guard`;
CREATE TEMPORARY TABLE `_exodus_guard` (`ok` INT NOT NULL);
LEFT JOIN `_exodus_measured` s ON s.id=d.id AND s.point=d.point
WHERE d.id=4492802 AND (s.point IS NULL OR ABS(d.position_x-s.position_x)>0.001
OR ABS(d.position_y-s.position_y)>0.001 OR ABS(d.position_z-s.position_z)>0.001
OR d.orientation<>0 OR d.delay<>0 OR d.move_type<>1 OR d.action<>0 OR d.action_chance<>100 OR d.wpguid<>0) LIMIT 1;
SELECT s.* FROM `_exodus_measured` s
LEFT JOIN waypoint_data d ON d.id=s.id AND d.point=s.point
WHERE d.point IS NULL;
DROP TEMPORARY TABLE `_exodus_measured`, `_exodus_guard`;
